36	//
37	//              https://opensource.org/license/bsd-3-clause
38	//--------------------------------------------------------------------------
39	// Description:
40	//   DPE WireGuard Encryptor
41	//==========================================================================
42	
43	module dpe_wg_encryptor (
44	   dpe_if.s_axis        inp,
45	   dpe_if.m_axis        outp,
46	
47	   output logic         fcr_idle,
48	
49	   output logic [7:0]   ram_peer_idx,
50	   input  logic [47:0]  ram_local_mac,
51	   input  logic [31:0]  ram_local_ip,
52	   input  logic [15:0]  ram_local_port,
53	   input  logic [47:0]  ram_remote_mac,
54	   input  logic [31:0]  ram_remote_ip,
55	   input  logic [15:0]  ram_remote_port,
56	   input  logic [31:0]  ram_remote_id,
57	   input  logic [255:0] ram_encrypt_key,
58	   input  logic [63:0]  ram_send_cnt,
59	   output logic [63:0]  ram_new_send_cnt,
60	   output logic         ram_update_send_cnt
61	);
62	   import dpe_pkg::*;
63	
64	   typedef enum logic [3:0] {
65	      IDLE,
66	      BYPASS,
67	      WAIT_RAM,
68	      HEADER_1,
69	      HEADER_2,
70	      HEADER_3,
71	      HEADER_4,
72	      PAYLOAD,
73	      PAYLOAD_LAST
74	   } state_t;
75	
76	// Internal states
77	   state_t state, state_next;
78	   logic [2:0] tuser_dst, tuser_dst_next;
79	   logic [2:0] tuser_src, tuser_src_next;
80	   logic [7:0] peer_idx, peer_idx_next;
81	   logic [47:0] local_mac, local_mac_next;
82	   logic [31:0] local_ip, local_ip_next;
83	   logic [15:0] local_port, local_port_next;
84	   logic [47:0] remote_mac, remote_mac_next;
85	   logic [31:0] remote_ip, remote_ip_next;
86	   logic [15:0] remote_port, remote_port_next;
87	   logic [31:0] remote_id, remote_id_next;
88	   logic [255:0] encrypt_key, encrypt_key_next;
89	   logic [63:0] send_cnt, send_cnt_next;
90	   logic [63:0] new_send_cnt, new_send_cnt_next;
91	   logic update_send_cnt, update_send_cnt_next;
92	   logic [127:0] plaintext_data, plaintext_data_next;
93	   logic plaintext_valid, plaintext_valid_next;
94	   logic [127:0] encrypted_data, encrypted_data_next;
95	   logic input_finished, input_finished_next;
96	   logic [15:0] packet_ip_len, packet_ip_len_next;
97	   logic [15:0] packet_udp_len, packet_udp_len_next;
98	
99	// Internal signals
100	   dpe_if to_encrypt (.clk(inp.clk), .rst(inp.rst));
101	   dpe_if from_encrypt (.clk(inp.clk), .rst(inp.rst));
102	   dpe_if piped (.clk(inp.clk), .rst(inp.rst));
103	   dpe_if muxed (.clk(inp.clk), .rst(inp.rst));
104	
105	// FSM registers
106	   always_ff @(posedge inp.clk) begin
107	      if (inp.rst) begin
108	         state <= IDLE;
109	         tuser_dst <= '0;
110	         tuser_src <= '0;
111	         peer_idx <= '0;
112	         local_mac <= '0;
113	         local_ip <= '0;
114	         local_port <= '0;
115	         remote_ip <= '0;
116	         remote_port <= '0;
117	         remote_id <= '0;
118	         encrypt_key <= '0;
119	         send_cnt <= '0;
120	         new_send_cnt <= '0;
121	         update_send_cnt <= '0;
122	         plaintext_data <= '0;
123	         plaintext_valid <= 1'b0;
124	         encrypted_data <= '0;
125	         input_finished <= 1'b0;
126	         packet_ip_len <= '0;
127	         packet_udp_len <= '0;
128	      end else begin
129	         state <= state_next;
130	         tuser_dst <= tuser_dst_next;
131	         tuser_src <= tuser_src_next;
132	         peer_idx <= peer_idx_next;
133	         local_mac <= local_mac_next;
134	         local_ip <= local_ip_next;
135	         local_port <= local_port_next;
136	         remote_mac <= remote_mac_next;
137	         remote_ip <= remote_ip_next;
138	         remote_port <= remote_port_next;
139	         remote_id <= remote_id_next;
140	         encrypt_key <= encrypt_key_next;
141	         send_cnt <= send_cnt_next;
142	         new_send_cnt <= new_send_cnt_next;
143	         update_send_cnt <= update_send_cnt_next;
144	         plaintext_data <= plaintext_data_next;
145	         plaintext_valid <= plaintext_valid_next;
146	         encrypted_data <= encrypted_data_next;
147	         input_finished <= input_finished_next;
148	         packet_ip_len <= packet_ip_len_next;
149	         packet_udp_len <= packet_udp_len_next;
150	      end
151	   end
152	
153	// FSM transition logic
154	   always_comb begin
155	      state_next = state;
156	      tuser_dst_next = tuser_dst;
157	      tuser_src_next = tuser_src;
158	      peer_idx_next = peer_idx;
159	      local_mac_next = local_mac;
160	      local_ip_next = local_ip;
161	      local_port_next = local_port;
162	      remote_mac_next = remote_mac;
163	      remote_ip_next = remote_ip;
164	      remote_port_next = remote_port;
165	      remote_id_next = remote_id;
166	      encrypt_key_next = encrypt_key;
167	      send_cnt_next = send_cnt;
168	      new_send_cnt_next = new_send_cnt;
169	      update_send_cnt_next = update_send_cnt;
170	      plaintext_data_next = plaintext_data;
171	      plaintext_valid_next = plaintext_valid;
172	      encrypted_data_next = encrypted_data;
173	      input_finished_next = input_finished;
174	      packet_ip_len_next = packet_ip_len;
175	      packet_udp_len_next = packet_udp_len;
176	
177	      unique case (state)
178	         IDLE: begin
179	            if (inp.tvalid && inp.tready) begin
180	               if (inp.tuser_bypass_stage || inp.tuser_bypass_all) begin
181	                  state_next = BYPASS;
182	               end else begin
183	                  tuser_dst_next = inp.tuser_dst;
184	                  tuser_src_next = inp.tuser_src;
185	                  peer_idx_next = inp.tid;
186	                  state_next = WAIT_RAM;
187	               end
188	            end
189	         end
190	
191	         BYPASS: begin
192	            if (inp.tlast && inp.tvalid) begin
193	               state_next = IDLE;
194	            end
195	         end
196	
197	         WAIT_RAM: begin
198	            local_mac_next = ram_local_mac;
199	            local_ip_next = ram_local_ip;
200	            local_port_next = ram_local_port;
201	            remote_mac_next = ram_remote_mac;
202	            remote_ip_next = ram_remote_ip;
203	            remote_port_next = ram_remote_port;
204	            remote_id_next = ram_remote_id;
205	            encrypt_key_next = ram_encrypt_key;
206	            send_cnt_next = ram_send_cnt;
207	
208	            if (piped.tvalid && piped.tready) begin
209	               plaintext_data_next = piped.tdata;
210	            end
211	            plaintext_valid_next = piped.tvalid;
212	
213	            if (muxed.tready) begin
214	               state_next = HEADER_1;
215	            end
216	         end
217	
218	         HEADER_1: begin
219	            if (piped.tvalid && piped.tready) begin
220	               plaintext_data_next = piped.tdata;
221	               /* verilator lint_off WIDTHEXPAND */
222	               /* verilator lint_off WIDTHTRUNC */
223	               packet_ip_len_next[15:0] = {piped.tdata[7:0], piped.tdata[15:12], 4'd0} + 16'd76;
224	               packet_udp_len_next[15:0] = {piped.tdata[7:0], piped.tdata[15:12], 4'd0} + 16'd56;
225	               /* verilator lint_on WIDTHEXPAND */
226	               /* verilator lint_on WIDTHTRUNC */
227	               state_next = HEADER_2;
228	            end
229	            plaintext_valid_next = piped.tvalid;
230	         end
231	
232	         HEADER_2: begin
233	            if (piped.tvalid && piped.tready) begin
234	               plaintext_data_next = piped.tdata;
235	               if (piped.tlast) begin
236	                  input_finished_next = 1'b1;
237	               end
238	               state_next = HEADER_3;
239	            end
240	            plaintext_valid_next = piped.tvalid;
241	         end
242	
243	         HEADER_3: begin
244	            if (piped.tvalid && piped.tready) begin
245	               plaintext_data_next = piped.tdata;
246	               if (piped.tlast) begin
247	                  input_finished_next = 1'b1;
248	               end
249	               state_next = HEADER_4;
250	            end
251	            plaintext_valid_next = piped.tvalid;
252	         end
253	
254	         HEADER_4: begin
255	            if (piped.tvalid && piped.tready) begin
256	               plaintext_data_next = piped.tdata;
257	               if (piped.tlast) begin
258	                  input_finished_next = 1'b1;
259	               end
260	            end
261	            plaintext_valid_next = piped.tvalid;
262	
263	            if (muxed.tready && from_encrypt.tvalid) begin
264	               encrypted_data_next = from_encrypt.tdata;
265	               state_next = PAYLOAD;
266	            end
267	         end
268	
269	         PAYLOAD: begin
270	            if (piped.tvalid && piped.tready) begin
271	               plaintext_data_next = piped.tdata;
272	               if (piped.tlast) begin
273	                  input_finished_next = 1'b1;
274	               end
275	            end
276	            plaintext_valid_next = piped.tvalid;
277	
278	            if (muxed.tready && from_encrypt.tvalid) begin
279	               encrypted_data_next = from_encrypt.tdata;
280	               if (from_encrypt.tlast) begin
281	                  new_send_cnt_next = send_cnt + 1;
282	                  update_send_cnt_next = 1'b1;
283	                  state_next = PAYLOAD_LAST;
284	               end
285	            end
286	         end
287	
288	         PAYLOAD_LAST: begin
289	            update_send_cnt_next = 1'b0;
290	            if (muxed.tready) begin
291	               input_finished_next = 1'b0;
292	               state_next = IDLE;
293	            end
294	         end
295	
296	         default: state_next = IDLE;
297	      endcase
298	   end
299	
300	// Outputs logic
301	   always_comb begin
302	      to_encrypt.tvalid = 1'b0;
303	      to_encrypt.tdata = '0;
304	      to_encrypt.tlast = 1'b0;
305	      to_encrypt.tkeep = '0;
306	
307	      muxed.tvalid = 1'b0;
308	      muxed.tdata = '0;
309	      muxed.tlast = 1'b0;
310	      muxed.tkeep = '0;
311	      muxed.tuser_bypass_all = 1'b0;
312	      muxed.tuser_bypass_stage = 1'b0;
313	      muxed.tuser_src = '0;
314	      muxed.tuser_dst = '0;
315	      muxed.tid = '0;
316	
317	      unique case (state)
318	         IDLE, BYPASS: begin
319	            muxed.tvalid = piped.tvalid;
320	            muxed.tdata = piped.tdata;
321	            muxed.tlast = piped.tlast;
322	            muxed.tkeep = piped.tkeep;
323	            muxed.tuser_bypass_all = piped.tuser_bypass_all;
324	            muxed.tuser_bypass_stage = piped.tuser_bypass_stage;
325	            muxed.tuser_src = piped.tuser_src;
326	            muxed.tuser_dst = piped.tuser_dst;
327	            muxed.tid = piped.tid;
328	         end
329	
330	         WAIT_RAM: begin
331	            //NOP
332	         end
333	
334	         HEADER_1: begin
335	            to_encrypt.tvalid = piped.tvalid;
336	            to_encrypt.tdata = {piped.tdata[111:0], plaintext_data[127:112]};
337	            to_encrypt.tlast = 1'b0;
338	            to_encrypt.tkeep = 16'hFFFF;
339	
340	            muxed.tvalid = 1'b1;
341	            //             IP:DSCP IP:VER ETH:TL    ETH:SA     ETH:DA
342	            muxed.tdata = {8'h00, 8'h45, 16'h0008, local_mac, remote_mac};
343	            muxed.tlast = 1'b0;
344	            muxed.tkeep = 16'hFFFF;
345	            muxed.tuser_bypass_all = 1'b0;
346	            muxed.tuser_bypass_stage = 1'b0;
347	            muxed.tuser_dst = tuser_dst;
348	            muxed.tuser_src = tuser_src;
349	            muxed.tid = peer_idx;
350	         end
351	
352	         HEADER_2: begin
353	            to_encrypt.tvalid = piped.tvalid;
354	            to_encrypt.tdata = {piped.tdata[111:0], plaintext_data[127:112]};
355	            to_encrypt.tlast = 1'b0;
356	            to_encrypt.tkeep = 16'hFFFF;
357	
358	            muxed.tvalid = 1'b1;
359	            //             IP:DA            IP:SA           IP:HCHK  IP:PROT IP:TTL IP:FLG    IP:ID     IP:TL
360	            muxed.tdata = {remote_ip[15:0], local_ip[31:0], 16'h0000, 8'h11, 8'd64, 16'h0000, 16'h0000, packet_ip_len[7:0], packet_ip_len[15:8]};
361	            muxed.tlast = 1'b0;
362	            muxed.tkeep = 16'hFFFF;
363	            muxed.tuser_bypass_all = 1'b0;
364	            muxed.tuser_bypass_stage = 1'b0;
365	            muxed.tuser_dst = tuser_dst;
366	            muxed.tuser_src = tuser_src;
367	            muxed.tid = peer_idx;
368	         end
369	
370	         HEADER_3: begin
371	            to_encrypt.tvalid = (piped.tkeep[15:14] == 2'b00) ? plaintext_valid : piped.tvalid;
372	            to_encrypt.tdata = {piped.tdata[111:0], plaintext_data[127:112]};
373	            to_encrypt.tlast = (piped.tkeep[15:14] == 2'b00) ? 1'b1 : 1'b0;
374	            to_encrypt.tkeep = 16'hFFFF;
375	
376	            muxed.tvalid = 1'b1;
377	            //             WG:RCV           WG:TYPE       UDP:CHK   UDP:LEN                                    UDP:DP       UDP:SP      IP:DA
378	            muxed.tdata = {remote_id[15:0], 32'h00000004, 16'h0000, packet_udp_len[7:0], packet_udp_len[15:8], remote_port, local_port, remote_ip[31:16]};
379	            muxed.tlast = 1'b0;
380	            muxed.tkeep = 16'hFFFF;
381	            muxed.tuser_bypass_all = 1'b0;
382	            muxed.tuser_bypass_stage = 1'b0;
383	            muxed.tuser_dst = tuser_dst;
384	            muxed.tuser_src = tuser_src;
385	            muxed.tid = peer_idx;
386	         end
387	
388	         HEADER_4: begin
389	            to_encrypt.tvalid = (piped.tkeep[15:14] == 2'b00) ? plaintext_valid : piped.tvalid;
390	            to_encrypt.tdata = {piped.tdata[111:0], plaintext_data[127:112]};
391	            to_encrypt.tlast = (piped.tkeep[15:14] == 2'b00) ? 1'b1 : 1'b0;
392	            to_encrypt.tkeep = 16'hFFFF;
393	
394	            muxed.tvalid = from_encrypt.tvalid;
395	            //             WG:ENP WG:CNT    WG:RCV
396	            muxed.tdata = {from_encrypt.tdata[47:0], send_cnt, remote_id[31:16]};
397	            muxed.tlast = 1'b0;
398	            muxed.tkeep = 16'hFFFF;
399	            muxed.tuser_bypass_all = 1'b0;
400	            muxed.tuser_bypass_stage = 1'b0;
401	            muxed.tuser_dst = tuser_dst;
402	            muxed.tuser_src = tuser_src;
403	            muxed.tid = peer_idx;
404	         end
405	
406	         PAYLOAD: begin
407	            to_encrypt.tvalid = (piped.tkeep[15:14] == 2'b00) ? plaintext_valid : piped.tvalid;
408	            to_encrypt.tdata = {piped.tdata[111:0], plaintext_data[127:112]};
409	            to_encrypt.tlast = (piped.tkeep[15:14] == 2'b00) ? 1'b1 : 1'b0;
410	            to_encrypt.tkeep = 16'hFFFF;
411	
412	            muxed.tvalid = from_encrypt.tvalid;
413	            //             WG:ENP
414	            muxed.tdata = {from_encrypt.tdata[47:0], encrypted_data[127:48]};
415	            muxed.tlast = 1'b0;
416	            muxed.tkeep = 16'hFFFF;
417	            muxed.tuser_bypass_all = 1'b0;
418	            muxed.tuser_bypass_stage = 1'b0;
419	            muxed.tuser_dst = tuser_dst;
420	            muxed.tuser_src = tuser_src;
421	            muxed.tid = peer_idx;
422	         end
423	
424	         PAYLOAD_LAST: begin
425	            muxed.tvalid = 1'b1;
426	            //             WG:ENP
427	            muxed.tdata = {48'd0, encrypted_data[127:48]};
428	            muxed.tlast = 1'b1;
429	            muxed.tkeep = 16'h03FF;
430	            muxed.tuser_bypass_all = 1'b0;
431	            muxed.tuser_bypass_stage = 1'b0;
432	            muxed.tuser_dst = tuser_dst;
433	            muxed.tuser_src = tuser_src;
434	            muxed.tid = peer_idx;
435	         end
436	
437	         default: begin
438	            to_encrypt.tdata = '0;
439	            to_encrypt.tkeep = '0;
440	            to_encrypt.tlast = '0;
441	            to_encrypt.tvalid = '0;
442	
443	            muxed.tdata = '0;
444	            muxed.tkeep = '0;
445	            muxed.tlast = '0;
446	            muxed.tvalid = '0;
447	            muxed.tuser_bypass_all = 1'b0;
448	            muxed.tuser_bypass_stage = 1'b0;
449	            muxed.tuser_src = '0;
450	            muxed.tuser_dst = '0;
451	            muxed.tid = '0;
452	         end
453	      endcase
454	   end
455	   assign piped.tready = muxed.tready & to_encrypt.tready & ~input_finished;
456	   assign from_encrypt.tready = muxed.tready;
457	   assign fcr_idle = ((state == IDLE) ? 1'b1 : 1'b0) & ~outp.tvalid;
458	   assign ram_peer_idx = peer_idx;
459	   assign ram_new_send_cnt = new_send_cnt;
460	   assign ram_update_send_cnt = update_send_cnt;
461	
462	// Encryptor core
463	   chacha20poly1305_encrypt u_chacha20poly1305_encrypt (
464	      .clk_80p0(inp.clk),
465	      .key(encrypt_key),
466	      .nonce({32'd0, send_cnt}),
467	      .aad(256'd0),
468	      .aad_len(8'd0),
469	      .s_axis_tdata(to_encrypt.tdata),
470	      .s_axis_tkeep(to_encrypt.tkeep),
471	      .s_axis_tlast(to_encrypt.tlast),
472	      .s_axis_tvalid(to_encrypt.tvalid),
473	      .m_axis_tready(from_encrypt.tready),
474	      .s_axis_tready(to_encrypt.tready),
475	      .m_axis_tdata(from_encrypt.tdata),
476	      .m_axis_tkeep(from_encrypt.tkeep),
477	      .m_axis_tlast(from_encrypt.tlast),
478	      .m_axis_tvalid(from_encrypt.tvalid)
479	   );
480	
481	// Input pipeline
482	   dpe_if_pipeline #(
483	      .LENGTH(1)
484	   ) u_dpe_if_pipeline_input (
485	      .inp(inp),
486	      .outp(piped)
487	   );
488	
489	// Output skid buffer
490	   dpe_if_skid_buffer u_dpe_if_skid_buffer_output (
491	      .inp(muxed),
492	      .outp(outp)
493	   );
494	endmodule
495

