39	// Description:
40	//    DPE WireGuard Decryptor with Verification Gate & Ethernet Re-wrap
41	//==========================================================================
42	
43	// ============================================================================
44	// Module: sync_fifo
45	// Description: Internal buffer to hold decrypted data until verified.
46	// ============================================================================
47	
48	module sync_fifo #(
49	    parameter WIDTH = 159,
50	    parameter DEPTH = 512
51	)(
52	    input  logic             clk,
53	    input  logic             rst,
54	    input  logic [WIDTH-1:0] data_in,
55	    input  logic             wr_en,
56	    output logic             full,
57	    output logic [WIDTH-1:0] data_out,
58	    input  logic             rd_en,
59	    output logic             empty
60	);
61	    localparam ADDR_W = $clog2(DEPTH);
62	    logic [WIDTH-1:0] mem [DEPTH];
63	    logic [ADDR_W:0]  wr_ptr, rd_ptr;
64	
65	    assign full  = (wr_ptr[ADDR_W] != rd_ptr[ADDR_W]) && (wr_ptr[ADDR_W-1:0] == rd_ptr[ADDR_W-1:0]);
66	    assign empty = (wr_ptr == rd_ptr);
67	
68	    always_ff @(posedge clk) begin
69	        if (rst) begin
70	            wr_ptr <= '0;
71	            rd_ptr <= '0;
72	        end else begin
73	            if (wr_en && !full) begin
74	                mem[wr_ptr[ADDR_W-1:0]] <= data_in;
75	                wr_ptr <= wr_ptr + 1;
76	            end
77	            if (rd_en && !empty) begin
78	                rd_ptr <= rd_ptr + 1;
79	            end
80	        end
81	    end
82	    assign data_out = mem[rd_ptr[ADDR_W-1:0]];
83	endmodule
84	
85	// ============================================================================
86	// Module: dpe_wg_decryptor
87	// Description: Main decryptor with FIFO-based verification gating.
88	// ============================================================================
89	
90	module dpe_wg_decryptor (
91	   dpe_if.s_axis        inp,
92	   dpe_if.m_axis        outp,
93	   output logic          fcr_idle,
94	   output logic [7:0]    ram_peer_idx,
95	   input  logic [47:0]   ram_local_mac,
96	   input  logic [31:0]   ram_local_ip,
97	   input  logic [15:0]   ram_local_port,
98	   input  logic [47:0]   ram_remote_mac,
99	   input  logic [31:0]   ram_remote_ip,
100	   input  logic [15:0]   ram_remote_port,
101	   input  logic [31:0]   ram_remote_id,
102	   input  logic [255:0]  ram_decrypt_key,
103	   input  logic [63:0]   ram_send_cnt,
104	   output logic [63:0]   ram_new_send_cnt,
105	   output logic          ram_update_send_cnt
106	);
107	   import dpe_pkg::*;
108	
109	   typedef enum logic [3:0] {
110	      IDLE,
111	      BYPASS,
112	      WAIT_RAM,
113	      HEADER_1,
114	      HEADER_2,
115	      HEADER_3,
116	      HEADER_4,
117	      PAYLOAD,
118	      PAYLOAD_LAST,
119	      DROP_PACKET
120	   } state_t;
121	
122	   // Internal states
123	   state_t state, state_next;
124	   logic [2:0] tuser_dst, tuser_dst_next;
125	   logic [2:0] tuser_src, tuser_src_next;
126	   logic [7:0] peer_idx, peer_idx_next;
127	   logic [47:0] local_mac, local_mac_next;
128	   logic [31:0] local_ip, local_ip_next;
129	   logic [15:0] local_port, local_port_next;
130	   logic [47:0] remote_mac, remote_mac_next;
131	   logic [31:0] remote_ip, remote_ip_next;
132	   logic [15:0] remote_port, remote_port_next;
133	   logic [31:0] remote_id, remote_id_next;
134	   logic [255:0] decrypt_key, decrypt_key_next;
135	   logic [63:0] send_cnt, send_cnt_next;
136	   logic [63:0] new_send_cnt, new_send_cnt_next;
137	   logic update_send_cnt, update_send_cnt_next;
138	   logic [127:0] plaintext_data, plaintext_data_next;
139	   logic plaintext_valid, plaintext_valid_next;
140	   logic [127:0] decrypted_data, decrypted_data_next;
141	   logic input_finished, input_finished_next;
142	   logic [15:0] packet_ip_len, packet_ip_len_next;
143	   logic [15:0] packet_udp_len, packet_udp_len_next;
144	
145	   // Internal signals
146	   dpe_if to_decrypt (.clk(inp.clk), .rst(inp.rst));
147	   dpe_if from_decrypt (.clk(inp.clk), .rst(inp.rst));
148	   dpe_if piped (.clk(inp.clk), .rst(inp.rst));
149	   dpe_if muxed (.clk(inp.clk), .rst(inp.rst));
150	   logic is_verified;
151	
152	   // FIFO & Gate Logic Signals
153	   logic packet_authorized;
154	   logic fifo_full, fifo_empty, fifo_clear;   
155	
156	   // FIFO Data Packing (tdata + tkeep + tlast + tuser signals)
157	   localparam FIFO_W = 128 + 16 + 1 + 3 + 3 + 8;
158	   logic [FIFO_W-1:0] fifo_din, fifo_dout;
159	
160	   assign fifo_din = {
161	      muxed.tid,             // [158:151]
162	      muxed.tuser_src,       // [150:148]
163	      muxed.tuser_dst,       // [147:145]
164	      muxed.tlast,           // [144]
165	      muxed.tkeep,           // [143:128]
166	      muxed.tdata            // [127:0]
167	   };
168	
169	   // Output Logic mapping from FIFO
170	   logic        fifo_out_tlast;
171	   logic [15:0] fifo_out_tkeep;
172	   logic [127:0] fifo_out_tdata;
173	   logic [2:0]  fifo_out_tuser_dst, fifo_out_tuser_src;
174	   logic [7:0]  fifo_out_tid;
175	
176	   assign {fifo_out_tid, fifo_out_tuser_src, fifo_out_tuser_dst, 
177	           fifo_out_tlast, fifo_out_tkeep, fifo_out_tdata} = fifo_dout;
178	
179	   // FIFO Instantiation
180	   sync_fifo #(.WIDTH(FIFO_W), .DEPTH(512)) out_fifo (
181	      .clk(inp.clk),
182	      .rst(inp.rst || fifo_clear),
183	      .data_in(fifo_din),
184	      .wr_en(muxed.tvalid && !fifo_full),
185	      .full(fifo_full),
186	      .data_out(fifo_dout),
187	      .rd_en(outp.tready && packet_authorized),
188	      .empty(fifo_empty)
189	   );
190	
191	   // Verification Gate: Opens only if is_verified is true at the end of packet
192	   always_ff @(posedge inp.clk) begin
193	      if (inp.rst || fifo_clear) begin
194	         packet_authorized <= 1'b0;
195	      end else if (state == PAYLOAD_LAST && is_verified) begin
196	         packet_authorized <= 1'b1; 
197	      end else if (outp.tlast && outp.tready) begin
198	         packet_authorized <= 1'b0; 
199	      end
200	   end
201	
202	   // FSM registers
203	   always_ff @(posedge inp.clk) begin
204	      if (inp.rst) begin
205	         state <= IDLE;
206	         tuser_dst <= '0; tuser_src <= '0; peer_idx <= '0;
207	         local_mac <= '0; local_ip <= '0; local_port <= '0;
208	         remote_mac <= '0; remote_ip <= '0; remote_port <= '0; remote_id <= '0;
209	         decrypt_key <= '0; send_cnt <= '0; new_send_cnt <= '0; update_send_cnt <= '0;
210	         plaintext_data <= '0; plaintext_valid <= 1'b0; decrypted_data <= '0;
211	         input_finished <= 1'b0; packet_ip_len <= '0; packet_udp_len <= '0;
212	      end else begin
213	         state <= state_next;
214	         tuser_dst <= tuser_dst_next; tuser_src <= tuser_src_next; peer_idx <= peer_idx_next;
215	         local_mac <= local_mac_next; local_ip <= local_ip_next; local_port <= local_port_next;
216	         remote_mac <= remote_mac_next; remote_ip <= remote_ip_next; remote_port <= remote_port_next;
217	         remote_id <= remote_id_next; decrypt_key <= decrypt_key_next;
218	         send_cnt <= send_cnt_next; new_send_cnt <= new_send_cnt_next; update_send_cnt <= update_send_cnt_next;
219	         plaintext_data <= plaintext_data_next; plaintext_valid <= plaintext_valid_next;
220	         decrypted_data <= decrypted_data_next; input_finished <= input_finished_next;
221	         packet_ip_len <= packet_ip_len_next; packet_udp_len <= packet_udp_len_next;
222	      end
223	   end
224	
225	   // FSM transition logic
226	   always_comb begin
227	      state_next = state;
228	      tuser_dst_next = tuser_dst; tuser_src_next = tuser_src; peer_idx_next = peer_idx;
229	      local_mac_next = local_mac; local_ip_next = local_ip; local_port_next = local_port;
230	      remote_mac_next = remote_mac; remote_ip_next = remote_ip; remote_port_next = remote_port;
231	      remote_id_next = remote_id; decrypt_key_next = decrypt_key; send_cnt_next = send_cnt;
232	      new_send_cnt_next = new_send_cnt; update_send_cnt_next = update_send_cnt;
233	      plaintext_data_next = plaintext_data; plaintext_valid_next = plaintext_valid;
234	      decrypted_data_next = decrypted_data; input_finished_next = input_finished;
235	      packet_ip_len_next = packet_ip_len; packet_udp_len_next = packet_udp_len;
236	      fifo_clear = 1'b0;
237	
238	      unique case (state)
239	         IDLE: begin
240	            if (inp.tvalid && inp.tready) begin
241	               if (inp.tuser_bypass_stage || inp.tuser_bypass_all) state_next = BYPASS;
242	               else begin
243	                  tuser_dst_next = inp.tuser_dst;
244	                  tuser_src_next = inp.tuser_src;
245	                  peer_idx_next = inp.tid;
246	                  state_next = WAIT_RAM;
247	               end
248	            end
249	         end
250	
251	         BYPASS: if (inp.tlast && inp.tvalid) state_next = IDLE;
252	
253	         WAIT_RAM: begin
254	            local_mac_next = ram_local_mac; 
255	            local_ip_next = ram_local_ip;
256	            local_port_next = ram_local_port; 
257	            remote_mac_next = ram_remote_mac;
258	            remote_ip_next = ram_remote_ip; 
259	            remote_port_next = ram_remote_port;
260	            remote_id_next = ram_remote_id; 
261	            decrypt_key_next = ram_decrypt_key;
262	            send_cnt_next = ram_send_cnt;
263	            if (piped.tvalid && piped.tready) plaintext_data_next = piped.tdata;
264	            plaintext_valid_next = piped.tvalid;
265	            if (!fifo_full) state_next = HEADER_1;
266	         end
267	
268	         HEADER_1: begin
269	
270	            if (piped.tvalid && piped.tready) begin
271	
272	               plaintext_data_next = piped.tdata;
273	               packet_ip_len_next = {piped.tdata[7:0], piped.tdata[15:12], 4'd0} + 16'd76;
274	               packet_udp_len_next = {piped.tdata[7:0], piped.tdata[15:12], 4'd0} + 16'd56;
275	               state_next = HEADER_2;
276	            end
277	            plaintext_valid_next = piped.tvalid;
278	         end
279	
280	         HEADER_2: begin
281	            if (piped.tvalid && piped.tready) begin
282	               plaintext_data_next = piped.tdata;
283	               if (piped.tlast) input_finished_next = 1'b1;
284	               state_next = HEADER_3;
285	            end
286	            plaintext_valid_next = piped.tvalid;
287	         end
288	
289	
290	         HEADER_3: begin
291	            if (piped.tvalid && piped.tready) begin
292	               plaintext_data_next = piped.tdata;
293	               if (piped.tlast) input_finished_next = 1'b1;
294	               state_next = HEADER_4;
295	            end
296	            plaintext_valid_next = piped.tvalid;
297	         end
298	
299	
300	         HEADER_4: begin
301	            if (piped.tvalid && piped.tready) begin
302	               plaintext_data_next = piped.tdata;
303	               if (piped.tlast) input_finished_next = 1'b1;
304	            end
305	            plaintext_valid_next = piped.tvalid;
306	            if (!fifo_full && from_decrypt.tvalid) begin
307	               decrypted_data_next = from_decrypt.tdata;
308	               state_next = PAYLOAD;
309	            end
310	         end
311	
312	
313	         PAYLOAD: begin
314	            if (piped.tvalid && piped.tready) begin
315	               plaintext_data_next = piped.tdata;
316	               if (piped.tlast) input_finished_next = 1'b1;
317	            end
318	
319	            plaintext_valid_next = piped.tvalid;
320	            if (!fifo_full && from_decrypt.tvalid) begin
321	               decrypted_data_next = from_decrypt.tdata;
322	               if (from_decrypt.tlast) begin
323	                  new_send_cnt_next = send_cnt + 1;
324	                  update_send_cnt_next = 1'b1;
325	                  state_next = PAYLOAD_LAST;
326	               end
327	            end
328	         end
329	
330	         PAYLOAD_LAST: begin
331	            update_send_cnt_next = 1'b0;
332	            if (!fifo_full) begin
333	               if (is_verified) begin
334	                  input_finished_next = 1'b0;
335	                  state_next = IDLE;
336	               end else begin
337	                  state_next = DROP_PACKET;
338	               end
339	            end
340	         end
341	
342	
343	         DROP_PACKET: begin
344	            fifo_clear = 1'b1;
345	            input_finished_next = 1'b0;
346	            state_next = IDLE;
347	         end
348	
349	
350	         default: state_next = IDLE;
351	      endcase
352	   end
353	
354	   // Outputs logic (Muxing and Data Generation)
355	
356	   always_comb begin
357	      to_decrypt.tvalid = 1'b0; 
358	      to_decrypt.tdata = '0; 
359	      to_decrypt.tlast = 1'b0; 
360	      to_decrypt.tkeep = '0;
361	      muxed.tvalid = 1'b0; 
362	      muxed.tdata = '0; 
363	      muxed.tlast = 1'b0; 
364	      muxed.tkeep = '0;
365	      muxed.tuser_bypass_all = 1'b0; 
366	      muxed.tuser_bypass_stage = 1'b0;
367	      muxed.tuser_src = tuser_src; 
368	      muxed.tuser_dst = tuser_dst; 
369	      muxed.tid = peer_idx;
370	
371	
372	      unique case (state)
373	
374	         IDLE, BYPASS: begin
375	            muxed.tvalid = piped.tvalid; 
376	            muxed.tdata = piped.tdata; 
377	            muxed.tlast = piped.tlast;
378	            muxed.tkeep = piped.tkeep; 
379	            muxed.tuser_bypass_all = piped.tuser_bypass_all;
380	            muxed.tuser_bypass_stage = piped.tuser_bypass_stage; 
381	            muxed.tuser_src = piped.tuser_src;
382	            muxed.tuser_dst = piped.tuser_dst; 
383	            muxed.tid = piped.tid;
384	         end
385	
386	
387	         HEADER_1: begin
388	            to_decrypt.tvalid = piped.tvalid;
389	            to_decrypt.tdata = {piped.tdata[111:0], plaintext_data[127:112]};
390	            to_decrypt.tkeep = 16'hFFFF;
391	            muxed.tvalid = !fifo_full;
392	            muxed.tdata = {8'h00, 8'h45, 16'h0008, local_mac, remote_mac};
393	            muxed.tkeep = 16'hFFFF;
394	         end
395	
396	
397	         HEADER_2: begin
398	            to_decrypt.tvalid = piped.tvalid;
399	            to_decrypt.tdata = {piped.tdata[111:0], plaintext_data[127:112]};
400	            to_decrypt.tkeep = 16'hFFFF;
401	            muxed.tvalid = !fifo_full;
402	            muxed.tdata = {remote_ip[15:0], local_ip[31:0], 16'h0000, 8'h11, 8'd64, 16'h0000, 16'h0000, packet_ip_len[7:0], packet_ip_len[15:8]};
403	            muxed.tkeep = 16'hFFFF;
404	         end
405	
406	
407	         HEADER_3: begin
408	            to_decrypt.tvalid = (piped.tkeep[15:14] == 2'b00) ? plaintext_valid : piped.tvalid;
409	            to_decrypt.tdata = {piped.tdata[111:0], plaintext_data[127:112]};
410	            to_decrypt.tlast = (piped.tkeep[15:14] == 2'b00) ? 1'b1 : 1'b0;
411	            to_decrypt.tkeep = 16'hFFFF;
412	            muxed.tvalid = !fifo_full;
413	            muxed.tdata = {remote_id[15:0], 32'h00000004, 16'h0000, packet_udp_len[7:0], packet_udp_len[15:8], remote_port, local_port, remote_ip[31:16]};
414	            muxed.tkeep = 16'hFFFF;
415	         end
416	
417	
418	         HEADER_4: begin
419	            to_decrypt.tvalid = (piped.tkeep[15:14] == 2'b00) ? plaintext_valid : piped.tvalid;
420	            to_decrypt.tdata = {piped.tdata[111:0], plaintext_data[127:112]};
421	            to_decrypt.tlast = (piped.tkeep[15:14] == 2'b00) ? 1'b1 : 1'b0;
422	            to_decrypt.tkeep = 16'hFFFF;
423	            muxed.tvalid = !fifo_full && from_decrypt.tvalid;
424	            muxed.tdata = {from_decrypt.tdata[47:0], send_cnt, remote_id[31:16]};
425	            muxed.tkeep = 16'hFFFF;
426	         end
427	
428	
429	         PAYLOAD: begin
430	            to_decrypt.tvalid = (piped.tkeep[15:14] == 2'b00) ? plaintext_valid : piped.tvalid;
431	            to_decrypt.tdata = {piped.tdata[111:0], plaintext_data[127:112]};
432	            to_decrypt.tlast = (piped.tkeep[15:14] == 2'b00) ? 1'b1 : 1'b0;
433	            to_decrypt.tkeep = 16'hFFFF;
434	            muxed.tvalid = !fifo_full && from_decrypt.tvalid;
435	            muxed.tdata = {from_decrypt.tdata[47:0], decrypted_data[127:48]};
436	            muxed.tkeep = 16'hFFFF;
437	         end
438	
439	
440	         PAYLOAD_LAST: begin
441	            muxed.tvalid = !fifo_full;
442	            muxed.tdata = {48'd0, decrypted_data[127:48]};
443	            muxed.tlast = 1'b1;
444	            muxed.tkeep = 16'h03FF;
445	         end
446	         default: ; 
447	      endcase
448	   end
449	
450	
451	   // Handshaking and interface assignments
452	   assign piped.tready = !fifo_full && to_decrypt.tready && !input_finished;
453	   assign from_decrypt.tready = !fifo_full;
454	   assign fcr_idle = ((state == IDLE) ? 1'b1 : 1'b0) && !outp.tvalid;
455	   assign ram_peer_idx = peer_idx;
456	   assign ram_new_send_cnt = new_send_cnt;
457	   assign ram_update_send_cnt = update_send_cnt;
458	
459	
460	   // Drive the external interface from FIFO outputs
461	   assign outp.tvalid = !fifo_empty && packet_authorized;
462	   assign outp.tlast  = fifo_out_tlast;
463	   assign outp.tkeep  = fifo_out_tkeep;
464	   assign outp.tdata  = fifo_out_tdata;
465	   assign outp.tid    = fifo_out_tid;
466	   assign outp.tuser_dst = fifo_out_tuser_dst;
467	   assign outp.tuser_src = fifo_out_tuser_src;
468	
469	   // Sub-module instantiations
470	
471	   chacha20poly1305_decrypt decrypt (
472	      .clk_80p0(inp.clk),
473	      .key(decrypt_key),
474	      .nonce({32'd0, send_cnt}),
475	      .aad(256'd0),
476	      .aad_len(8'd0),
477	      .s_axis_tdata(to_decrypt.tdata),
478	      .s_axis_tkeep(to_decrypt.tkeep),
479	      .s_axis_tlast(to_decrypt.tlast),
480	      .s_axis_tvalid(to_decrypt.tvalid),
481	      .m_axis_tready(from_decrypt.tready),
482	      .s_axis_tready(to_decrypt.tready),
483	      .m_axis_tdata(from_decrypt.tdata),
484	      .m_axis_tkeep(from_decrypt.tkeep),
485	      .m_axis_tlast(from_decrypt.tlast),
486	      .m_axis_tvalid(from_decrypt.tvalid),
487	      .m_verified(is_verified)
488	   );
489	
490	   dpe_if_pipeline #(.LENGTH(1)) input_pipe (
491	      .inp(inp),
492	      .outp(piped)
493	   );
494	endmodule 
